   [222]={next_id=223, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯米娅日记\n今天，和店长、链尉官、冷蛟战员一起定下来了店铺的庆祝活动。\n冷蛟战员说人类会在看到喜欢的人的时候温度升高，这一定是很重要的信息，必须记下来。\n今天看到了店长笑，她从来没有这么开心过，是因为链尉官的原因吗？", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT301_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.50, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 913.00, 341.00, 1.00, {}, {}}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
